css:
/* Рисованная линия: подчёркивание, обводка, стрелка к кнопке.
   Анимируется stroke-dashoffset — узкое исключение из правила «только transform и opacity»:
   меняется рисунок одной тонкой SVG-линии, раскладка страницы не пересчитывается.
   pathLength="1" делает путь длиной 1 при любой форме, поэтому числа ниже не зависят от рисунка. */
.sld { position: relative; display: inline-block; white-space: nowrap; } /* 1–3 слова: фраза не переносится, линия лежит под ней целиком */
.sld__svg, .sld__arrow {
  overflow: visible;
  pointer-events: none;
  fill: none;
  stroke: var(--sld-color, var(--primary, #2446d8)); /* контраст линии с фоном от 3:1 */
  stroke-width: var(--sld-width, 3px);
  stroke-linecap: round;
  stroke-linejoin: round;
}
.sld__svg { position: absolute; left: -3%; width: 106%; }
.sld__svg--under { top: 92%; height: .32em; }                        /* под строкой: оставьте line-height от 1.15, иначе линия заденет следующую строку */
.sld--circle { margin-inline: .3em; }                              /* обводке нужны поля: иначе она задевает соседнее тире или запятую */
.sld__svg--circle { left: -12%; width: 124%; top: -22%; height: 144%; }
.sld__svg path, .sld__arrow path { vector-effect: non-scaling-stroke; } /* толщина линии не тянется вместе с растянутой картинкой */
.sld-cta { display: flex; align-items: center; gap: 8px; }
.sld__arrow { flex: none; width: 96px; height: 64px; }

/* Ждёт своей очереди: спрятана только под .sld-on (строчка в <head>). Без JS, в печати и у роботов линия видна сразу */
.sld-on [data-sld]:not([data-sld="draw"]) path { stroke-dasharray: 1 2; stroke-dashoffset: 1.01; }
[data-sld="draw"] path {
  stroke-dasharray: 1 2;
  stroke-dashoffset: 0;
  transition: stroke-dashoffset var(--sld-dur, 600ms) cubic-bezier(.65, 0, .35, 1) var(--sld-delay, 0ms); /* рука: разгон и торможение */
}
.sld__svg--circle { --sld-dur: 800ms; } /* обводка длиннее подчёркивания */
/* Наконечник стрелки дорисовывается после древка (перехлёст 15 %) */
[data-sld="draw"] path + path {
  transition-duration: calc(var(--sld-dur, 600ms) * .4);
  transition-delay: calc(var(--sld-delay, 0ms) + var(--sld-dur, 600ms) * .85);
}
@media (max-width: 640px) {
  .sld__arrow { display: none; }
}
/* Уменьшение движения (уровень «убрать»): линии нарисованы сразу, без прорисовки */
@media (prefers-reduced-motion: reduce) {
  .sld-on [data-sld] path { stroke-dashoffset: 0 !important; transition: none !important; }
}
@media print {
  [data-sld] path { stroke-dashoffset: 0 !important; }
}

