// Рисованная линия: без зависимостей. Рисует один раз, когда линия почти вся в кадре.
(() => {
  window.__sld = true; // сигнал строчке в <head>: скрипт жив, класс не снимать
  const els = document.querySelectorAll('[data-sld]');
  if (!els.length) return;
  if (!('IntersectionObserver' in window)) { document.documentElement.classList.remove('sld-on'); return; } // всё нарисовано
  const io = new IntersectionObserver((es) => es.forEach((e) => {
    if (!e.isIntersecting) return;
    io.unobserve(e.target); // один раз, без повтора при прокрутке назад
    const el = e.target;
    el.style.setProperty('--sld-delay', (parseFloat(el.dataset.sldDelay) || 0) + 'ms');
    el.dataset.sld = 'draw';
  }), { threshold: 0.6, rootMargin: '0px 0px -10% 0px' });
  els.forEach((el) => io.observe(el));
})();

