// GSAP ради одной линии не нужен: CSS делает то же без библиотек. Если GSAP уже есть (npm i gsap, без CDN) —
// строчку в <head> и CSS рецепта оставить, JS рецепта заменить этим. GSAP пишет stroke-dashoffset в style,
// это перекрывает скрытое состояние из CSS; правило reduce в CSS с !important всё равно рисует линию сразу.
import { gsap } from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';
gsap.registerPlugin(ScrollTrigger);
window.__sld = true; // сигнал строчке в <head>: скрипт жив

const mm = gsap.matchMedia();
mm.add({ motion: '(prefers-reduced-motion: no-preference)', reduce: '(prefers-reduced-motion: reduce)' }, ({ conditions }) => {
  gsap.utils.toArray('[data-sld]').forEach((el) => {
    const [shaft, head] = el.querySelectorAll('path');
    if (conditions.reduce) { gsap.set([shaft, head].filter(Boolean), { strokeDashoffset: 0 }); return; }
    const tl = gsap.timeline({ paused: true, delay: (parseFloat(el.dataset.sldDelay) || 0) / 1000 })
      .fromTo(shaft, { strokeDashoffset: 1.01 }, { strokeDashoffset: 0, duration: 0.6, ease: 'power2.inOut' });
    if (head) tl.fromTo(head, { strokeDashoffset: 1.01 }, { strokeDashoffset: 0, duration: 0.24, ease: 'power2.out' }, '-=0.09'); // наконечник
    ScrollTrigger.create({ trigger: el, start: 'top 85%', once: true, onEnter: () => tl.play() });
  });
}); // matchMedia сам откатит анимации при смене настройки
